# ==========================================
# BASE AGENT
# ==========================================
"""
agents/base_agent.py

Defines the BaseAgent class that all Player and Opponent modeling agents inherit from.
This ensures a unified interface structure across the entire codebase.
"""

from typing import Any

class BaseAgent:
    def __init__(self, perspective_flag: str):
        """
        Initializes the agent.
        
        Parameters
        ----------
        perspective_flag : str
            Either 'player' or 'opponent' to mark state ownership.
        """
        self.perspective_flag = perspective_flag

    def receive(self, packet: Any) -> Any:
        """
        Processes an incoming packet and returns a response.
        Must be implemented by child classes.
        """
        raise NotImplementedError("Subclasses must implement receive()")

# ==========================================
# ROUTER / BUS
# ==========================================

__all__ = [
    "HandAnalystPacket", "TurnPlannerPacket", "StrategyPacket",
    "TimePacket", "OpponentModelPacket", "LethalPacket",
    "Router", "ScopeViolationError", "UnknownAgentError", "PACKET_SCHEMAS",
    "RouterBus",
]

# ==========================================
# SUB-AGENTS
# ==========================================
"""
agents/registry.py

Decorator-based agent registration system.
Each sub-agent class decorates itself with @register_agent to declare its
bus name, constructor parameter requirements, and optional RouterBus metadata.
The Orchestrator discovers all registered agents via get_registered_agents()
instead of hardcoding imports.
"""

from typing import Any, Callable, Dict, List, Optional, Type

# ---------------------------------------------------------------------------
# Internal registry storage
# ---------------------------------------------------------------------------
_AGENT_REGISTRY: Dict[str, dict] = {}


def register_agent(
    bus_name: str,
    *,
    perspective_flag: str = "player",
    needs_skills_dir: bool = True,
    needs_shared_context: bool = True,
):
    """
    Class decorator that registers a sub-agent for automatic discovery.

    Parameters
    ----------
    bus_name : str
        The name used when calling ``RouterBus.register_agent(bus_name, ...)``.
    perspective_flag : str
        The perspective flag passed to ``RouterBus.register_agent`` (default ``"player"``).
    needs_skills_dir : bool
        If True the orchestrator will pass ``skills_dir`` to the constructor.
    needs_shared_context : bool
        If True the orchestrator will pass ``shared_context`` to the constructor.
    """

    def decorator(cls: Type) -> Type:
        if bus_name in _AGENT_REGISTRY:
            raise ValueError(
                f"Duplicate agent registration: bus_name '{bus_name}' "
                f"is already registered to {_AGENT_REGISTRY[bus_name]['cls'].__name__}"
            )
        _AGENT_REGISTRY[bus_name] = {
            "cls": cls,
            "perspective_flag": perspective_flag,
            "needs_skills_dir": needs_skills_dir,
            "needs_shared_context": needs_shared_context,
        }
        return cls

    return decorator


def get_registered_agents() -> Dict[str, dict]:
    """
    Returns a *copy* of the current agent registry.

    Each value is a dict with keys:
        cls                 – the agent class
        perspective_flag    – 'player' or 'opponent'
        needs_skills_dir    – bool
        needs_shared_context – bool
    """
    try:
        import importlib
        for m in ["hand_analyst", "turn_planner", "strategy_agent", "opponent_model", "time_manager"]:
            try:
                importlib.import_module(f"agents.{m}")
            except ImportError:
                pass
    except Exception:
        pass
    return dict(_AGENT_REGISTRY)


def clear_registry() -> None:
    """Clears the registry.  Useful in tests to avoid cross-contamination."""
    _AGENT_REGISTRY.clear()

import json
import pathlib
import datetime
from typing import Any
import logging

logger = logging.getLogger(__name__)

_PROJECT_ROOT = pathlib.Path(__file__).resolve().parent.parent
_SKILL_PATH   = _PROJECT_ROOT / "skills" / "card_scoring.json"
_LOG_PATH     = _PROJECT_ROOT / "logs"   / "reasoning_log.json"

_PROFILE_THRESHOLDS: list[tuple[float, str]] = [
    (7.0, "aggressive"),
    (4.0, "tempo"),
    (0.0, "defensive"),
]


class HandAnalyst:
    def __init__(self, **kwargs: Any) -> None:
        self.skills_dir = pathlib.Path(kwargs.get("skills_dir")) if kwargs.get("skills_dir") else _PROJECT_ROOT / "skills"
        self.log_dir = pathlib.Path(kwargs.get("log_dir")) if kwargs.get("log_dir") else _PROJECT_ROOT / "logs"
        self._scoring_db: dict[str, dict[str, Any]] = self._load_skill()
        self._log_buffer: list[dict[str, Any]] = []

    def flush_logs(self) -> None:
        log_path = self.log_dir / "reasoning_log.json"
        log_path.parent.mkdir(parents=True, exist_ok=True)
        flush_reasoning_logs(self._log_buffer, log_path, logger)

    def analyse(self, packet: dict[str, Any]) -> dict[str, Any]:
        if hasattr(packet, "model_dump"): packet = packet.model_dump()
        elif hasattr(packet, "_asdict"): packet = packet._asdict()
        elif hasattr(packet, "__dict__"): packet = packet.__dict__
        hand: list[str]    = packet["hand"]
        deck_remaining: int = packet.get("deck_remaining", 0)
        scored_cards        = self._score_hand(hand)
        hand_score          = self._mean_ev(scored_cards)
        priority_profile    = self._derive_profile(hand_score)
        top_play            = self._best_card(scored_cards)
        result = {
            "hand_score":       round(hand_score, 4),
            "priority_profile": priority_profile,
            "top_play":         top_play,
        }
        self._log(hand, deck_remaining, scored_cards, result)
        return result

    receive = analyse

    def _load_skill(self) -> dict[str, dict[str, Any]]:
        skill_path = self.skills_dir / "card_scoring.json"
        try:
            raw = json.loads(skill_path.read_text(encoding="utf-8"))
        except FileNotFoundError:
            raw = {"cards": []}
        index = {}
        for entry in raw.get("cards", []):
            name = entry.get("card_name", "").strip()
            if name:
                index[name.lower()] = entry
        return index

    def _score_hand(self, hand: list[str]) -> list[tuple[str, float]]:
        return score_hand_helper(hand, self._scoring_db)

    def _mean_ev(self, scored_cards: list[tuple[str, float]]) -> float:
        return mean_ev_helper(scored_cards)

    def _derive_profile(self, hand_score: float) -> str:
        return derive_profile_helper(hand_score, _PROFILE_THRESHOLDS)

    def _best_card(self, scored_cards: list[tuple[str, float]]) -> str:
        return best_card_helper(scored_cards)

    def _log(self, hand, deck_remaining, scored_cards, result):
        entry: dict[str, Any] = {
            "timestamp": datetime.datetime.now(datetime.timezone.utc).isoformat(timespec="milliseconds") + "Z",
            "agent":     "HandAnalyst",
            "input":     {"hand": hand, "deck_remaining": deck_remaining},
            "reasoning": {
                "card_scores":   [{"card": n, "ev_score": e} for n, e in scored_cards],
                "unknown_cards": [n for n, e in scored_cards if e == 0.0],
            },
            "output": result,
        }
        self._log_buffer.append(entry)

import json
import logging
from pathlib import Path
from typing import Any


logger = logging.getLogger(__name__)

@register_agent("turn_planner")
class TurnPlanner(BaseAgent):
    def __init__(self, log_dir="logs", skills_dir="skills", perspective_flag="player", shared_context=None, belief_tracker=None):
        super().__init__(perspective_flag)
        self.log_dir = Path(log_dir)
        self.skills_dir = Path(skills_dir)
        self.shared_context = shared_context
        self.log_dir.mkdir(parents=True, exist_ok=True)
        self.skills_dir.mkdir(parents=True, exist_ok=True)
        try:
            self.rules = (self.shared_context.get_config(str(self.skills_dir), "priority_rules.json")
                          if self.shared_context else self._load_priority_rules())
        except Exception as e:
            logger.error(f"Failed to get_config: {e}")
            self.rules = {"rules": []}
        self.mcts = MCTSEngine(num_simulations=50, belief_tracker=belief_tracker)
        self._logger = TurnPlannerLogger(self.log_dir)
        self._prize_tracker = PrizeTracker()
        self._consecutive_passes = 0

    def _load_priority_rules(self) -> dict:
        return PRIORITY_RULES

    def receive(self, packet: Any) -> dict:
        if isinstance(packet, dict):
            packet = TurnPlannerPacket(**packet)
        if not isinstance(packet, TurnPlannerPacket):
            raise TypeError(f"TurnPlanner received an illegal packet type: {type(packet).__name__}.")
        try:
            game_state = getattr(packet, "game_state", {}) or {}
            turn = getattr(packet, "turn", 1)
            profile = packet.priority_profile
            if profile not in {"aggressive", "defensive", "tempo", "aggro_push", "setup", "disruption", "stall", "closing"}:
                logger.warning(f"Unknown profile '{profile}', falling back to aggro_push")
                profile = "aggro_push"
            game_state["priority_profile"] = profile
            game_state = _process_prize_tracker(game_state, self._prize_tracker, packet)
            game_state["has_searched_deck"] = game_state.get("prize_certainty", 0.0) > 0
            candidates = build_legal_candidates(game_state)
            if self._consecutive_passes >= 10 and "pass" in candidates and len(candidates) > 1:
                logger.warning(f"10-Pass Hard Limit Reached. Forcefully removing 'pass' to break stalemate.")
                candidates.remove("pass")
            time_rem = getattr(packet, "time_remaining", 600.0)
            _check_lethal_and_update(game_state)
            primary, reasoning = resolve_action(candidates, game_state, profile, time_rem, self.mcts, self.rules)
            if primary == "pass":
                self._consecutive_passes += 1
            else:
                self._consecutive_passes = 0
            
            sorted_actions = sort_actions_heuristically(candidates, profile, game_state)
            if primary:
                if primary in sorted_actions:
                    sorted_actions.remove(primary)
                sorted_actions.insert(0, primary)
            else:
                primary = sorted_actions[0] if sorted_actions else "pass"
            if not sorted_actions:
                sorted_actions = ["pass"]
            response = {"action_sequence": sorted_actions, "primary_action": primary, "reasoning_chain": reasoning}
            self._logger.log_reasoning(turn, profile, response)
            return response
        except Exception as e:
            logger.error(f"TurnPlanner.receive failed: {e}", exc_info=True)
            return {"action_sequence": ["pass"], "primary_action": "pass", "reasoning_chain": "error_fallback"}

    def get_prize_tracker(self) -> PrizeTracker:
        return self._prize_tracker

    def flush_logs(self):
        try:
            self._logger.flush_logs()
        except Exception as e:
            logger.error(f"flush_logs failed: {e}")

"""Board-strategy selection agent. Delegates I/O to strategy_agent_io."""

from typing import Any

_CONF_EXACT_KEY = 1.0
_CONF_KEYWORD = 0.75
_CONF_FALLBACK = 0.3
_FALLBACK_PROFILE_KEY = "hand_dead"


class StrategyAgent:
    """Selects the best strategic posture for the current board state."""

    def __init__(self, **kwargs: Any) -> None:
        try:
            self._profiles: dict[str, dict[str, Any]] = load_skill(kwargs.get("skills_dir"))
        except Exception as e:
            self._profiles = {}

    def evaluate(self, packet: dict[str, Any]) -> dict[str, Any]:
        try:
            return self._evaluate_internal(packet)
        except Exception as e:
            return {
                "strategy": "error_fallback",
                "posture": "tempo",
                "actions": ["PASS"],
                "escalation": "PASS",
                "confidence": 0.0,
            }

    def _evaluate_internal(self, packet: dict[str, Any]) -> dict[str, Any]:
        if hasattr(packet, "model_dump"): packet = packet.model_dump()
        elif hasattr(packet, "_asdict"): packet = packet._asdict()
        elif hasattr(packet, "__dict__"): packet = packet.__dict__
        if not isinstance(packet, dict):
            packet = {}
        trigger: str = str(packet.get("trigger", "")).strip()
        board_summary: dict = packet.get("board_summary", {})
        
        # Turn 1 Bad Deck Early Warning System
        if board_summary.get("turn_number", packet.get("turn", 0)) == 1 and not hasattr(self, "_checked_deck"):
            self._checked_deck = True
            deck = packet.get("deck", []) or board_summary.get("deck", [])
            if deck:
                elements = set()
                basics = 0
                for cid in deck:
                    c = _registry.get(int(cid) if str(cid).isdigit() else cid)
                    if c and c.card_type.name == "POKEMON":
                        # Simulate stage check, but simpler for now:
                        basics += 1
                        # Wait, CardEntry doesn't have element_type directly. We will pull it from registry full skill.
                        try:
                            full = _registry.get_full_skill(int(cid))
                            if full and hasattr(full, "element_type"):
                                elements.add(full.element_type)
                        except Exception:
                            pass
                if len(elements) >= 4 or (len(deck) > 20 and basics < 3):
                    import logging
                    logging.getLogger("StrategyAgent").error(f"CRITICAL WARNING: Executing with a highly unoptimized/brick-risk deck! Detected {len(elements)} elemental types.")
                    print(f"CRITICAL WARNING: Executing with a highly unoptimized/brick-risk deck! Detected {len(elements)} elemental types.")

        profile_key, profile, confidence, match_reason = self._match_profile(
            trigger, board_summary
        )
        result: dict[str, Any] = {
            "strategy":   profile_key,
            "posture":    profile.get("posture", "tempo"),
            "actions":    profile.get("actions", ["PASS"]),
            "escalation": profile.get("escalation", "PASS"),
            "confidence": round(confidence, 4),
        }
        self._log(packet, profile_key, match_reason, result)
        return result

    receive = evaluate

    def _match_profile(
        self,
        trigger: str,
        board_summary: dict[str, Any],
    ) -> tuple[str, dict[str, Any], float, str]:
        trigger_lower = trigger.lower()
        if trigger_lower in self._profiles:
            return trigger_lower, self._profiles[trigger_lower], _CONF_EXACT_KEY, "exact key match"
        
        board_match = board_signal_match(board_summary)
        if board_match:
            key = board_match
            if key not in self._profiles:
                raise ValueError(f"CRITICAL SILENT FAILURE PREVENTED: Strategy key '{key}' is missing from strategy_profiles.json!")
            return key, self._profiles[key], _CONF_KEYWORD, f"board_summary signal -> {key}"
            
        best_key, best_score = keyword_scan(trigger_lower, self._profiles)
        if best_key and best_score > 0:
            return (
                best_key,
                self._profiles[best_key],
                _CONF_KEYWORD * best_score,
                f"keyword scan score={best_score:.2f}",
            )
            
        if _FALLBACK_PROFILE_KEY not in self._profiles:
            raise ValueError(f"CRITICAL SILENT FAILURE PREVENTED: Fallback key '{_FALLBACK_PROFILE_KEY}' is missing from strategy_profiles.json!")
        fallback = self._profiles[_FALLBACK_PROFILE_KEY]
        return _FALLBACK_PROFILE_KEY, fallback, _CONF_FALLBACK, "no match -> fallback"

    def _log(
        self,
        packet: dict[str, Any],
        matched_key: str,
        match_reason: str,
        result: dict[str, Any],
    ) -> None:
        log_strategy(packet, matched_key, match_reason, result, list(self._profiles.keys()))

import json
import logging
from pathlib import Path
from typing import Any, Dict

logger = logging.getLogger(__name__)
@register_agent("opponent_model", perspective_flag="opponent")
class OpponentModel(BaseAgent):
    def __init__(self, log_dir: str = "logs", skills_dir: str = "skills", perspective_flag: str = "opponent", shared_context=None):
        super().__init__(perspective_flag)
        self.log_dir = Path(log_dir)
        self.skills_dir = Path(skills_dir)
        self.shared_context = shared_context
        self.log_dir.mkdir(parents=True, exist_ok=True)
        self.skills_dir.mkdir(parents=True, exist_ok=True)
        self.reasoning_log_file = self.log_dir / "opponent_model_reasoning.json"
        self._reasoning_buffer = []
        if self.shared_context:
            self.archetypes = self.shared_context.get_config(str(self.skills_dir), "deck_archetypes.json").get("archetypes", {})
        else:
            self.archetypes = self._load_deck_archetypes()
        self.revealed_state = []
        self.inferred_state = {}
        self.archetype_confidence = 0.0
        self.identified_archetype = "unknown"
        self.opponent_searched_last_turn = False

    def _load_deck_archetypes(self) -> dict:
        return DECK_ARCHETYPES.get("archetypes", {})

    def receive(self, packet: Any) -> dict:
        if hasattr(packet, "_asdict"): packet = packet._asdict()
        elif hasattr(packet, "__dict__"): packet = packet.__dict__
        if not isinstance(packet, dict):
            raise TypeError(f"OpponentModel received illegal packet type: {type(packet).__name__}.")

        revealed_cards = packet.get("revealed_cards") or packet.get("newly_played_cards", [])
        turn_number = packet.get("turn_number") or packet.get("turn", 1)
        prizes_remaining = packet.get("prizes_remaining") or packet.get("revealed_prizes_remaining", 6)

        for card in revealed_cards:
            if card not in self.revealed_state:
                self.revealed_state.append(card)

        # IDENTIFY ARCHETYPE
        self.identified_archetype, self.archetype_confidence = identify_opponent_archetype(
            self.revealed_state, self.archetypes
        )

        # FILL INFERRED STATE
        if self.identified_archetype != "unknown" and self.identified_archetype in self.archetypes:
            pool = self.archetypes[self.identified_archetype].get("card_pool", [])
            self.inferred_state = {c: 1.0 for c in pool if c not in self.revealed_state}
        else:
            self.inferred_state = {}

        # PREDICT ACTION
        predicted = predict_opponent_action(self.identified_archetype, prizes_remaining, turn_number)

        reasoning = f"Identified {self.identified_archetype} with {round(self.archetype_confidence * 100, 2)}% confidence. Predicting {predicted}."

        self._reasoning_buffer.append({
            "turn": turn_number,
            "perspective": self.perspective_flag,
            "revealed_count": len(self.revealed_state),
            "identified_archetype": self.identified_archetype,
            "confidence": self.archetype_confidence,
            "predicted_next_action": predicted,
            "reasoning": reasoning,
            "opponent_searched_last_turn": self.opponent_searched_last_turn
        })

        return {
            "predicted_next_action": predicted,
            "archetype_confidence": self.archetype_confidence,
            "inferred_deck_type": self.identified_archetype,
            "reasoning": reasoning,
            "opponent_searched_last_turn": self.opponent_searched_last_turn
        }
    def flush_logs(self):
        if not self._reasoning_buffer:
            return
        try:
            with open(self.reasoning_log_file, "a", encoding="utf-8") as f:
                for entry in self._reasoning_buffer:
                    f.write(json.dumps(entry) + "\n")
            self._reasoning_buffer.clear()
        except Exception as e:
            logger.error(f"Failed to flush opponent model reasoning logs: {e}")

"""
agents/time_manager.py
----------------------
Monitors elapsed game time and enforces strict timeout-avoidance policy.

Contract
--------
- No skill file -- operates on hard-wired timing thresholds only.
- Input packet: { time_elapsed: float, time_limit: float } -- from Router only
- Output      : { directive: str, mode: str, urgency: float, time_remaining: float }
- Runs on every tick -- never sleeps, never blocks.
- Guarantees the game never times out.

Timing policy (spec)
--------------------
    time_elapsed <= 540 s  -> NORMAL    -- planner decides freely
    540 < elapsed <= 570 s -> FAST_MOVE -- force fastest legal move immediately
    elapsed > 570 s        -> FORCE_PASS -- force pass to avoid timeout
"""

import json
import pathlib
import datetime
from typing import Any

import logging

logger = logging.getLogger(__name__)

_PROJECT_ROOT         = pathlib.Path(__file__).resolve().parent.parent
_LOG_PATH             = _PROJECT_ROOT / "logs" / "reasoning_log.json"


class TimeManager:
    def __init__(self, **kwargs: Any):
        self.log_dir = pathlib.Path(kwargs.get("log_dir")) if kwargs.get("log_dir") else _PROJECT_ROOT / "logs"
        self._log_buffer: list[dict[str, Any]] = []

    def flush_logs(self) -> None:
        log_path = self.log_dir / "reasoning_log.json"
        log_path.parent.mkdir(parents=True, exist_ok=True)
        flush_reasoning_logs(self._log_buffer, log_path, logger)

    def tick(self, packet: dict[str, Any]) -> dict[str, Any]:
        if hasattr(packet, "model_dump"): packet = packet.model_dump()
        elif hasattr(packet, "_asdict"): packet = packet._asdict()
        elif hasattr(packet, "__dict__"): packet = packet.__dict__
        time_elapsed: float = float(packet.get("time_elapsed", 0.0))
        time_limit:   float = float(packet.get("time_limit",  600.0))
        directive, mode     = self._classify(time_elapsed, time_limit)
        urgency             = self._urgency(time_elapsed, time_limit)
        time_remaining      = max(0.0, time_limit - time_elapsed)
        result: dict[str, Any] = {
            "directive":      directive,
            "mode":           mode,
            "urgency":        round(urgency, 4),
            "time_remaining": round(time_remaining, 2),
        }
        self._log(packet, result, time_limit)
        return result

    receive = tick

    @staticmethod
    def _classify(time_elapsed: float, time_limit: float) -> tuple[str, str]:
        if time_elapsed > time_limit - 30.0:
            return "FORCE_PASS", "critical"
        if time_elapsed > time_limit - 60.0:
            return "FAST_MOVE", "urgent"
        return "NORMAL", "standard"

    @staticmethod
    def _urgency(time_elapsed: float, time_limit: float) -> float:
        if time_limit <= 0:
            return 1.0
        return min(1.0, max(0.0, time_elapsed / time_limit))

    def _log(self, packet, result, time_limit: float = 600.0):
        entry: dict[str, Any] = {
            "timestamp": datetime.datetime.now(datetime.timezone.utc).isoformat(timespec="milliseconds") + "Z",
            "agent":     "TimeManager",
            "input":     packet,
            "reasoning": {
                "threshold_fast":       time_limit - 60.0,
                "threshold_force_pass": time_limit - 30.0,
                "evaluation": f"time_elapsed={packet.get('time_elapsed')} -> directive={result['directive']}",
            },
            "output": result,
        }
        self._log_buffer.append(entry)

# ==========================================
# ORCHESTRATOR
# ==========================================
"""agents/orchestrator.py -- Thin shell that owns Orchestrator.

Delegates step logic to orchestrator_steps.py and logging to orchestrator_log.py.
"""

from typing import Any



class Orchestrator:
    def __init__(self, **kwargs: Any) -> None:
        delegation_map = {
            "TimeManager": "time_manager",
            "HandAnalyst": "hand_analyst",
            "TurnPlanner": "turn_planner",
            "StrategyAgent": "strategy_agent",
            "OpponentModel": "opponent_model"
        }
        self.bus = self._router = RouterBus(delegation_map=delegation_map, log_dir=kwargs.get("log_dir", "logs"))
        self.hand_analyst = self._analyst  = HandAnalyst(**kwargs)
        self.turn_planner = self._planner  = TurnPlanner(**kwargs)
        self.time_manager = self._timer    = TimeManager(**kwargs)
        self.strategy_agent = self._strategy = StrategyAgent(**kwargs)
        self.opponent_model = self._opponent = OpponentModel(**kwargs)
        self.context   = {}
        for agent in (self.hand_analyst, self.turn_planner, self.time_manager, self.strategy_agent, self.opponent_model):
            agent.shared_context = self.context

        self.bus.register_agent("time_manager", self._timer.tick)
        self.bus.register_agent("hand_analyst", self._analyst.analyse)
        self.bus.register_agent("turn_planner", self._planner.receive)
        self.bus.register_agent("strategy_agent", self._strategy.evaluate)
        self.bus.register_agent("opponent_model", self._opponent.receive, perspective_flag="opponent")

    def orchestrate(self, game_state: dict[str, Any]) -> TurnDecision:
        time_result = _step_time(game_state, self._timer, self._router)
        if time_result.get("directive") == "FORCE_PASS":
            return _emergency_pass(time_result)
        try:
            hand_result  = _step_hand(game_state, self._analyst, self._router)
            plan_result  = _step_plan(game_state, hand_result, self._planner, self._router)
            strat_result = _step_strategy(game_state, self._strategy, self._router)
            opp_result   = _step_opponent(game_state, self._opponent, self._router)
            decision     = _merge(game_state, time_result, hand_result, plan_result, strat_result, opp_result)
            _log_orchestration(game_state, decision)
            return decision
        except Exception:
            return _emergency_pass(time_result)

    def start_game(self) -> None:
        pass
        
    run_turn = orchestrate

    def flush_all_logs(self) -> None:
        try:
            self._timer.flush_logs()
        except Exception: pass
        try:
            self._analyst.flush_logs()
        except Exception: pass
        try:
            flush_strategy_logs()
        except Exception: pass
        try:
            flush_orch_logs()
        except Exception: pass

# ==========================================
# MAIN AGENT INTERFACE
# ==========================================
# GLOBAL SETUP (runs once on load)
try:
    orchestrator = Orchestrator()
    orchestrator.start_game()
except Exception as global_err:
    logger.error(f"Global orchestrator initialization failed: {global_err}")
    orchestrator = None

def get_val(obj, key, default=None):
    if isinstance(obj, dict):
        return obj.get(key, default)
    return getattr(obj, key, default)



def _log_action_exception(exc: Exception):
    log_dir = Path("logs")
    log_dir.mkdir(parents=True, exist_ok=True)
    log_file = log_dir / "action_log.json"
    
    error_entry = {
        "timestamp": "",
        "event": "submission_agent_crash",
        "agent_called": "submission/main.py",
        "packet_type": "exception",
        "error_reason": str(exc)
    }
    
    try:
        logs = []
        if log_file.exists():
            content = log_file.read_text(encoding="utf-8").strip()
            if content:
                try:
                    logs = json.loads(content)
                    if not isinstance(logs, list):
                        logs = [logs]
                except json.JSONDecodeError:
                    logs = []
        logs.append(error_entry)
        log_file.write_text(json.dumps(logs, indent=2), encoding="utf-8")
    except Exception as log_err:
        logger.error(f"Failed to log crash event to {log_file}: {log_err}")




